"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6490],{25658:e=>{e.exports=JSON.parse('{"functions":[{"name":"init","desc":"Bootstrap hook. Dispatches the opening `SECURITY_INIT` with the current\\nsecret, then hands off to [SecurityController.watch].","params":[],"returns":[],"function_type":"static","source":{"line":60,"path":"src/Client/Features/Core/Controllers/SecurityController.luau"}},{"name":"watch","desc":"Opens every listener the controller owns, for the session \u2014 nothing here\\nis disconnected.\\n\\n* `Player.Changed` for identity tampering (`UserId` / `Name`), which kicks.\\n* `CharacterAdded` -> `Humanoid.Changed` for speed and NaN-health\\n  tampering, which zeroes health.\\n* A `red.subscribe` catch-all that stores replacement secrets from\\n  `SECURITY_INIT` and answers `SECURITY_PING` with `SECURITY_PONG`.\\n\\nCalled by [SecurityController.init]; not meant to be called twice, since\\neach call adds another set of connections.","params":[],"returns":[],"function_type":"static","source":{"line":85,"path":"src/Client/Features/Core/Controllers/SecurityController.luau"}}],"properties":[],"types":[],"name":"SecurityController","desc":"Client half of the anti-exploit handshake. Answers the server\'s liveness\\nchallenge and locally reverts the two tampering patterns that are cheap to\\ncatch from the client.\\n\\n:::warning Client-side checks are advisory\\nEverything here runs on the exploiter\'s own machine and can be removed by\\nthem. Its value is the *ping/pong* leg: the server knows whether a client\\nis answering, and with what. Treat the local kick and the health reset as\\nfriction, never as enforcement \u2014 authority lives in the server services.\\n:::\\n\\n### The handshake\\n\\n[SecurityController.init] dispatches `SECURITY_INIT` carrying the current\\nsecret. The server is expected to answer with its own `SECURITY_INIT`\\ncarrying a replacement secret, which is stored and echoed back from then\\non. On each `SECURITY_PING` the controller replies `SECURITY_PONG` with\\nthe character\'s current `WalkSpeed` and the stored secret, so the server\\ncan compare both against what it believes.\\n\\n### Local watches\\n\\n* `Player.Changed` on `UserId` or `Name` \u2014 impossible under normal play, so\\n  the client kicks itself with \\"cheater\\".\\n* `Humanoid.Changed` \u2014 `WalkSpeed` above `GlobalConstants.MAX_WALKSPEED + 1`,\\n  or a NaN `Health` (compared as the `\\"-1.#IND\\"` string), zeroes the\\n  humanoid\'s health.\\n\\nBoth watches have a `SECURITY_OFFENSE` dispatch commented out beside them;\\nnothing dispatches or handles that action today.\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Client"],"source":{"line":39,"path":"src/Client/Features/Core/Controllers/SecurityController.luau"}}')}}]);